import os
import re

# Load the current instance's demos from recent messages
def load():
    d = os.environ['RLM_SESSION_DIR']
    session_file = os.path.join(d) + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        with open(session_file) as f:
            content = f.read().replace('\\n', '\n')
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        match = re.search(pattern, content)
        if match:
            k = match.group(1)
            h, w = int(match.group(2)), int(match.group(3))
            rows_lines = content[match.end():].split('\n')[:h]
            G = []
            for r in rows_lines:
                if r.strip():
                    G.append([int(x) for x in re.findall(r'\d+', r)])
            return {k: G}
        return {}
    except Exception as e:
        print(f"Error loading: {e}")
        return {}

G = load()
print("Loaded grids:", list(G.keys()))

if G:
    for k, grid in G.items():
        print(f"\n{k} ({len(grid)}x{len(grid[0])}):")
        for row in grid:
            print(" ".join(str(x) for x in row))

from collections import Counter

def transform(grid):
    if not grid:
        return grid
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    bg = counts.most_common(1)[0][0]
    result = [[bg] * len(grid[0])]
    for i in range(1, len(grid)):
        result.append(grid[i-1])
    return result

