from collections import Counter

def count_components(grid):
    """Count connected components of foreground pixels (4-connected)"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and not visited[r][c]:
                count += 1
                # BFS
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    visited[cr][cc] = True
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 8 and not visited[nr][nc]:
                            stack.append((nr, nc))
    return count

